contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try calling sendTo with arbitrary caller (this contract is the caller) and arbitrary receiver/amount.
    // The test ensures that if the call does not revert then msg.sender (this contract) must be the owner;
    // and if it reverts then C's balance remains unchanged.
    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        // record balance before
        uint256 beforeBal = address(c).balance;

        bool reverted;
        // perform the call and capture whether it reverts
        try c.sendTo{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: either it succeeded and this contract must be the owner (i.e., owner didn't revert check),
        // or it reverted and the contract balance must be unchanged.
        // We can observe owner only via behavior: if call succeeded, then owner == address(this) must hold because sendTo requires msg.sender == owner.
        // To check that, try a view call that would only succeed for owner: here we rely on behavioral implication: successful send implies caller was owner.
        // Formulate assertion: (not reverted) implies address(this) == tx.origin? No: tx.origin is external. Instead, we assert that if not reverted then address(this) != address(0) (tautology) -- avoid triviality.
        // Better: if not reverted then C's balance decreased by amount and receiver's balance increased by amount (but we cannot read receiver's balance reliably within contract), so instead assert that if not reverted then address(c).balance == beforeBal - amount.
        // If reverted then address(c).balance == beforeBal.

        assert(reverted ? address(c).balance == beforeBal : address(c).balance + amount == beforeBal);
    }

    receive() external payable {}
}

