contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller (as address) cannot be provided; calls originate from this contract.
    // We will test that when this contract (which is NOT the owner) calls sendTo, it must revert
    // unless this contract was the owner (i.e., deployed c). The checker deploys fresh c and
    // invokes run once — since c was deployed by the checker, not by this contract, this
    // contract is not the owner. So sendTo should revert for any inputs.

    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // record balances before
        uint balBeforeC = address(c).balance;
        uint balBeforeReceiver = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then msg.sender must have been owner. But in the test environment
        // c was freshly deployed by the checker, so this contract is not owner; therefore the call must revert.
        // We assert the general rule: when caller is not owner, sendTo reverts and balances unchanged.
        assert(reverted && address(c).balance == balBeforeC && receiver.balance == balBeforeReceiver);
    }

    receive() external payable {}
}

contract InvMutTest {
