    // We take receiver and amount as inputs. This contract will call c.sendTo(receiver, amount).
    // We observe balances before and after and whether the call reverted.
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // record balances before
        uint balBeforeC = address(c).balance;
        uint balBeforeReceiver = receiver.balance;
        uint balBeforeThis = address(this).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfterC = address(c).balance;
        uint balAfterReceiver = receiver.balance;
        uint balAfterThis = address(this).balance;

        // General rule: if sendTo succeeded, receiver's balance increased by exactly amount
        // and this contract's balance did not change; if sendTo reverted, balances are unchanged
        assert((!reverted && balAfterReceiver == balBeforeReceiver + amount && balAfterThis == balBeforeThis)
               || (reverted && balAfterC == balBeforeC && balAfterReceiver == balBeforeReceiver && balAfterThis == balBeforeThis));
    }

    receive() external payable {}
}

