    // then assert that revert happened iff one of the three preconditions (not owner, zero receiver, zero amount) holds.
    // Since this test contract is the deployer of C, msg.sender for c.call will be this contract, so ownership check passes.

    function run(address receiver, uint256 amount) public payable {
        require(address(this).balance >= 0); // no precondition on inputs

        bool reverted;
        try c.sendTo{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Determine the expected revert condition as visible externally:
        // - receiver == address(0) should cause revert (require(receiver != address(0)))
        // - amount == 0 should cause revert (require(amount > 0))
        // - caller != owner would cause revert, but in this setup caller == owner because this contract deployed c
        bool expectRevert = (receiver == address(0) || amount == 0);

        assert(reverted == expectRevert);
    }

    // Allow the test contract to receive Ether if needed by external setups
    receive() external payable {}
}

